mapper.select:
SELECT r.Resv_num AS resvNum, m.UserNickname AS userNickname, r.Resv_Status AS resvStatus, rm.RoomName AS roomName, p.PlanName AS planName, rr.Resv_CheckIn AS resvCheckIn, rr.Resv_CheckOut AS resvCheckOut, r.Resv_People AS resvPeople, r.Resv_Price AS resvPrice FROM RESERVATION r JOIN MEMBER m ON m.UserMail = r.UserMail LEFT JOIN ROOM_RESERVATION rr ON rr.Resv_num = r.Resv_num AND rr.RoomResv_num = ( SELECT MIN(rr2.RoomResv_num) FROM ROOM_RESERVATION rr2 WHERE rr2.Resv_num = r.Resv_num ) LEFT JOIN ROOM rm ON rm.RoomIdx = rr.RoomIdx LEFT JOIN PLAN p ON p.PlanIdx = rr.PlanIdx
r.AdminIdx = #{adminIdx}
ORDER BY r.Resv_num DESC
